  const fm=$('mform');if(fm){fm.addEventListener('input',e=>{if(e.target.id==='m-clSubj'||e.target.id==='m-clTo')clHead();});fm.addEventListener('change',e=>{if(e.target.name==='toPick')clHead();});}
